import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

type Entity = { id: number; nombre: string; codigo?: string; rol?: string; sucursalId?: number; ubicacionId?: number };
type User = { id: number; nombre: string; rol: string };
type Frequency = "diaria" | "semanal" | "quincenal" | "mensual" | "bimestral" | "trimestral" | "semestral" | "anual";
type Result = "pendiente" | "conforme" | "hallazgo" | "no_aplica";
type ScopeLocation = { id: number; nombre: string; position?: number };
type Zone = { id: number; name: string; siteId: number; version: number; locations: ScopeLocation[] };
type ZoneEditor = { zone?: Zone; name: string; siteId: number | null; locationIds: number[]; reason: string };
type PointConfig = { locationId?: number | null; measurementType?: "none" | "pressure"; measurementUnit?: string; photoRequired?: boolean; minValue?: number; maxValue?: number; limitSource?: string; mandatory?: boolean; code: string; group: string; label: string; criterion: string; active: boolean; exclusionReason: string; frequency: Frequency; firstDate: string; evidencePolicy: "none" | "findings" | "always"; assetId: number | null };
type TemplateConfig = { zoneId?: number | null; zoneName?: string; zoneVersion?: number; locations?: ScopeLocation[]; effectiveFrom: string; name: string; siteId: number | null; locationId: number | null; shift: string; timezoneOffset: string; time: string; windowMinutes: number; ownerId: number | null; backupId: number | null; reviewerId: number | null; reviewerBackupId: number | null; reason: string; points: PointConfig[]; notifications: { recipientIds: number[]; events: string[] } };
type Template = { id: number; name: string; version: number; config: TemplateConfig };
type Execution = { zoneId?: number | null; zoneName?: string; zone_id?: number | null; zone_name?: string; locations?: ScopeLocation[]; id: number; template_id: number; template_version: number; name: string; site_id: number; location_id: number; scheduled_date: string; shift: string; due_at: string; original_due_at: string; status: string; owner_id: number; backup_id: number | null; reviewer_id: number; reviewer_backup_id: number | null; executed_by: number | null; executed_at: string | null; reviewed_by: number | null; reviewed_at: string | null; revision: number; temporalStatus?: string };
type Point = { id: string; locationId?: number | null; locationName?: string; measurementType?: "none" | "pressure"; measurementUnit?: string; photoRequired?: boolean; minValue?: number; maxValue?: number; limitSource?: string; measurementValue?: number | null; evidenceId?: number | null; mandatory?: boolean; code: string; group?: string; label: string; criterion: string; assetId?: number | null; result: Result; notes?: string; evidence?: string; evidencePolicy?: string; observed_by?: number | null; observed_at?: string | null; order_id?: number | null };
type Draft = { result: Result; notes: string; evidence: string; measurementValue: number | ""; evidenceId: number | null };
type Evidence = { id: number; nombre: string; url: string };
type MaintenanceRecord = { id: number; planId: number; completadaEn?: string; verificadoEn?: string; verificadoPor?: number; asignadoA?: number; estado: string; verificadorNombre?: string; trabajosRealizados?: string; verificacionNotas?: string; evidenceTypes?: string[]; verified: boolean; verificationIssues?: string[]; evidence?: Evidence[] };
type Plan = { id: number; titulo: string; frecuencia: string; proximaFecha?: string; activo?: boolean; lastVerifiedExecution?: MaintenanceRecord | null; latestRecordedExecution?: MaintenanceRecord | null; latestUnverifiedExecution?: MaintenanceRecord | null; evidenceStatus?: string; daysElapsed?: number | null; nextDue?: string | null; overdue?: boolean; scheduleStatus?: string; complianceStatus?: string; managementStatus?: string; configuredNextDue?: string | null; scheduleDiscrepancy?: boolean; pendingOrders?: { id: number; titulo: string; estado: string; vencimiento?: string }[] };
type Equipment = { id: number; codigo: string; nombre: string; estado?: string; ubicacionNombre?: string; planes: Plan[]; capturedAt?: string };
type AuditEvent = { id: number; action: string; actor_id: number; actor_name?: string; created_at: string; details?: unknown };
type Notification = { id: number; event: string; status: string; attempts: number; last_error?: string; recipient_id: number; created_at: string };
type ManagedOrder = { id: number; titulo: string; tipo: string; estado: string; prioridad: string; vencimiento?: string; assignedName?: string; managementStatus: string; overdue: boolean };
type CandidateOrder = { id: number; titulo: string; estado: string; vencimiento?: string };
type LinkedOrder = { id: number; titulo?: string; estado: string; tipo?: string; prioridad?: string; pointId?: string };
type Detail = { execution: Execution; points: Point[]; equipment: Equipment[]; events: AuditEvent[]; notifications: Notification[]; linkedOrders?: LinkedOrder[]; proposals?: Proposal[] };
type Proposal = { id: number; point_id: string; kind: string; reason: string; status: string; priority?: string; order_id?: number | null; created_at: string; plan_id?: number | null };
type Catalog = { zones?: Zone[]; providers?: Entity[]; groups: { code: string; name: string; points: { code: string; label: string; criterion: string }[] }[]; sites: Entity[]; locations: Entity[]; users: Entity[]; assets: Entity[] };
const FREQUENCIES: Frequency[] = ["diaria", "semanal", "quincenal", "mensual", "bimestral", "trimestral", "semestral", "anual"];
const LABELS: Record<string, string> = { punto_guardado: "Punto guardado", generada: "Generada", ejecutada_tarde: "Ejecutada fuera de plazo", en_ventana: "En ventana", solicitud_creada: "Solicitud de acción creada", solicitud_aprobada: "Solicitud aprobada y programada", solicitud_devuelta: "Solicitud devuelta", solicitud_rechazada: "Solicitud rechazada", sin_historial: "Sin historial verificable", sin_config: "Sin configuración", sin_evidencia: "Sin evidencia", pendiente_aprobacion: "Pendiente de aprobación", sin_ot: "Sin OT", programada: "Programada", ejecutada_pendiente_validacion: "Ejecutada · pendiente de validación", verificada_cerrada: "Verificada / cerrada", pendiente: "Pendiente", asignada: "Asignada", en_progreso: "En progreso", en_curso: "En curso", pendiente_validacion: "Pendiente de validación", validada: "Validada", devuelta: "Devuelta", omitida: "Omitida", vencida: "Vencida", a_tiempo: "En plazo", en_plazo: "En plazo", conforme: "Conforme", hallazgo: "Hallazgo", no_aplica: "No aplica", dry_run: "Simulada · sin envío", pending: "Pendiente", sent: "Enviada", failed: "Fallida", save: "Punto guardado", submit: "Enviada a validar", approve: "Validada", return: "Devuelta", reschedule: "Reprogramada", miss: "Omitida", generated: "Generada", order: "OT vinculada", template_created: "Plantilla creada", template_versioned: "Nueva versión" };
const emptyCatalog: Catalog = { groups: [], sites: [], locations: [], users: [], assets: [] };
const today = () => new Date().toISOString().slice(0, 10);
const label = (value?: string | null) => value ? LABELS[value] || value.replace(/_/g, " ") : "Sin dato";
const date = (value?: string | null) => !value ? "Sin registro" : Number.isNaN(new Date(value).getTime()) ? value : new Date(value).toLocaleString("es", { dateStyle: "medium", timeStyle: "short" });
const nameOf = (items: Entity[], id?: number | null) => id ? items.find(item => item.id === id)?.nombre || `#${id}` : "Sin asignar";
const pointDraft = (point: Point): Draft => ({ result: point.result || "pendiente", notes: point.notes || "", evidence: point.evidence || "", measurementValue: point.measurementValue ?? "", evidenceId: point.evidenceId ?? null });
const safeEvidence = (value: string) => value.startsWith("/") && !value.startsWith("//") && !value.includes("\\");

async function request<T>(path: string, body?: unknown): Promise<T> {
  const response = await fetch(path, { credentials: "same-origin", headers: body === undefined ? undefined : { "content-type": "application/json" }, method: body === undefined ? "GET" : "POST", body: body === undefined ? undefined : JSON.stringify(body) });
  const data: any = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(response.status === 401 ? "Tu sesión terminó. Inicia sesión de nuevo; conserva esta pestaña para recuperar tus cambios." : response.status === 409 ? `${data.error || "La ronda cambió en otra sesión"}. Actualiza los datos y revisa tus cambios antes de guardar de nuevo.` : data.error || `No se pudo completar la solicitud (${response.status})`); Object.assign(error, { candidateOrders: data.candidateOrders, status: response.status }); throw error; }
  return data;
}
function Badge({ value, children }: { value?: string; children?: ReactNode }) {
  const style = ["validada", "conforme", "al_dia", "vigente"].includes(value || "") ? "bg-emerald-100 text-emerald-800" : ["vencida", "vencido", "hallazgo", "failed", "omitida"].includes(value || "") ? "bg-red-100 text-red-800" : ["pendiente_validacion", "devuelta", "sin_evidencia"].includes(value || "") ? "bg-amber-100 text-amber-900" : "bg-slate-100 text-slate-700";
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${style}`}>{children || label(value)}</span>;
}
function Field({ label: title, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="block min-w-0"><span className="label">{title}</span>{children}{hint && <span className="mt-1 block text-xs text-slate-500">{hint}</span>}</label>;
}
function EvidenceView({ value }: { value?: string }) {
  return !value ? <span>Sin evidencia adjunta</span> : safeEvidence(value) ? <a className="text-emerald-800 underline break-all" href={value} target="_blank" rel="noreferrer">Ver evidencia</a> : <span className="whitespace-pre-wrap break-words">{value}</span>;
}

export default function RondasApp({ user }: { user: User }) {
  const admin = ["admin", "jefe"].includes(user.rol);
  const [catalog, setCatalog] = useState<Catalog>(emptyCatalog);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [executions, setExecutions] = useState<Execution[]>([]);
  const [detail, setDetail] = useState<Detail | null>(null);
  const [drafts, setDrafts] = useState<Record<string, Draft>>({});
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [candidates, setCandidates] = useState<{ proposalId: number; orders: CandidateOrder[] } | null>(null);
  const activeIdRef = useRef<number | null>(null);
  const [busy, setBusy] = useState("");
  const busyRef = useRef(false);
  const fetchSequence = useRef(0);
  const [panel, setPanel] = useState<"rounds" | "templates" | "actions" | "zones">("rounds");
  const [managedOrders, setManagedOrders] = useState<ManagedOrder[]>([]);
  const [actionFilter, setActionFilter] = useState("open");
  const [filter, setFilter] = useState({ site: "", zone: "", zoneId: "", status: "", mine: !admin });
  const [onlyPending, setOnlyPending] = useState(false);
  const [pointGroup, setPointGroup] = useState("");
  const [pointLocation, setPointLocation] = useState("");
  const [editor, setEditor] = useState<{ template?: Template; config: TemplateConfig } | null>(null);
  const [editorDirty, setEditorDirty] = useState(false);
  const [editorScope, setEditorScope] = useState<"zone" | "location">("zone");
  const [zoneEditor, setZoneEditor] = useState<ZoneEditor | null>(null);
  const [zoneEditorDirty, setZoneEditorDirty] = useState(false);
  const [generation, setGeneration] = useState({ templateId: "", dateFrom: today(), dateTo: today() });
  const [actionDialog, setActionDialog] = useState<"approve" | "return" | "reschedule" | "miss" | null>(null);
  const [actionReason, setActionReason] = useState("");
  const [newDue, setNewDue] = useState("");
  const [orderDialog, setOrderDialog] = useState<{ pointId: string; kind: string; reason: string; existingOrderId: string; planId: string } | null>(null);
  const execution = detail?.execution;
  const dirty = detail ? detail.points.some(point => drafts[point.id] && JSON.stringify(drafts[point.id]) !== JSON.stringify(pointDraft(point))) : false;
  const storageKey = (id: number) => `rondas-draft:${user.id}:${id}`;
  const canEdit = !!execution && [execution.owner_id, execution.backup_id].includes(user.id) && !["pendiente_validacion", "validada", "omitida"].includes(execution.status);
  const isReviewer = !!execution && [execution.reviewer_id, execution.reviewer_backup_id].includes(user.id);
  const independentlyReviewable = isReviewer && execution?.executed_by !== user.id && !detail?.points.some(point => point.observed_by === user.id);
  const pending = detail?.points.filter(point => !point.result || point.result === "pendiente").length || 0;
  const answered = (detail?.points.length || 0) - pending;
  const returned = detail?.events.slice().reverse().find(event => ["return", "devuelta"].includes(event.action));

  async function loadList() {
    const data = await request<{ templates: Template[]; executions: Execution[] }>("/api/rondas");
    setTemplates(data.templates || []); setExecutions(data.executions || []);
    const actionData = await request<{ orders: ManagedOrder[] }>("/api/rondas/actions"); setManagedOrders(actionData.orders || []);
  }
  async function loadDetail(id: number, preserve = true) {
    const sequence = ++fetchSequence.current;
    if (activeIdRef.current !== id) setDetailLoading(true); activeIdRef.current = id; setError("");
    try {
      const data = await request<Detail>(`/api/rondas/executions/${id}`);
      if (sequence !== fetchSequence.current) return;
      setDetail({ ...data, equipment: data.equipment || [], events: data.events || [], notifications: data.notifications || [] });
      if (preserve) {
        try {
          const saved = JSON.parse(sessionStorage.getItem(storageKey(id)) || "{}");
          const safeDrafts: Record<string, Draft> = {};
          for (const point of data.points) if (saved[point.id] && ["pendiente", "conforme", "hallazgo", "no_aplica"].includes(saved[point.id].result) && typeof saved[point.id].notes === "string" && typeof saved[point.id].evidence === "string") safeDrafts[point.id] = { ...pointDraft(point), ...saved[point.id] };
          setDrafts(safeDrafts);
          if (Object.keys(safeDrafts).length) setNotice("Recuperamos los cambios sin enviar de esta pestaña. Revísalos y guarda cada punto.");
        } catch { setDrafts({}); }
      }
    } catch (err) { if (sequence === fetchSequence.current) setError((err as Error).message); }
    finally { if (sequence === fetchSequence.current) setDetailLoading(false); }
  }
  useEffect(() => {
    Promise.all([loadList(), request<Catalog>("/api/rondas/catalog").then(setCatalog)])
      .catch(err => setError(err.message)).finally(() => setLoading(false));
    const id = Number((new URLSearchParams(location.search).get("ejecucion") || new URLSearchParams(location.search).get("execution")));
    if (id) void loadDetail(id);
    const onPop = () => {
      if (busyRef.current) { history.pushState(null, "", activeIdRef.current ? `?ejecucion=${activeIdRef.current}` : location.pathname); setNotice("Espera a que termine el guardado antes de salir."); return; }
      const next = Number((new URLSearchParams(location.search).get("ejecucion") || new URLSearchParams(location.search).get("execution")));
      if (next) void loadDetail(next); else { fetchSequence.current++; setDetailLoading(false); setDetail(null); activeIdRef.current = null; setDrafts({}); }
    };
    window.addEventListener("popstate", onPop);
    return () => { window.removeEventListener("popstate", onPop); fetchSequence.current++; };
  }, []);
  useEffect(() => {
    const guard = (event: BeforeUnloadEvent) => { if (dirty || editorDirty || zoneEditorDirty || busy) { event.preventDefault(); event.returnValue = ""; } };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty, editorDirty, zoneEditorDirty, busy]);

  function updateDraft(point: Point, update: Partial<Draft>) {
    setDrafts(previous => {
      const next = { ...previous, [point.id]: { ...(previous[point.id] || pointDraft(point)), ...update } };
      try { sessionStorage.setItem(storageKey(detail!.execution.id), JSON.stringify(next)); }
      catch { setNotice("Los cambios están en esta pantalla, pero no se pudo crear una copia en la pestaña. Guarda antes de salir."); }
      return next;
    });
  }
  function openExecution(id: number) {
    if (busyRef.current) return;
    setNotice(""); setOnlyPending(false); setPointGroup(""); setPointLocation(""); setActionDialog(null); setOrderDialog(null);
    history.pushState(null, "", `?ejecucion=${id}`); void loadDetail(id);
  }
  function backToPanel() {
    if (busyRef.current) return;
    if (dirty && !window.confirm("Hay cambios sin enviar. Se conservarán en esta pestaña, pero aún no cuentan como guardados. ¿Volver al panel?")) return;
    fetchSequence.current++; setDetail(null); activeIdRef.current = null; setDrafts({}); setDetailLoading(false); setError(""); setNotice("");
    history.pushState(null, "", location.pathname); void loadList().catch(err => setError(err.message));
  }
  async function mutation(key: string, fn: () => Promise<void>) {
    if (busyRef.current) return;
    busyRef.current = true; setBusy(key); setError(""); setNotice("");
    try { await fn(); }
    catch (err) { setError((err as Error).message); const orders = (err as Error & { candidateOrders?: CandidateOrder[] }).candidateOrders; if (orders && key.startsWith("proposal:")) setCandidates({ proposalId: Number(key.split(":")[1]), orders }); }
    finally { busyRef.current = false; setBusy(""); }
  }
  async function savePoint(point: Point) {
    const draft = drafts[point.id] || pointDraft(point);
    if (point.measurementType === "pressure" && (draft.measurementValue === "" || !Number.isFinite(draft.measurementValue))) { setError("Registra la presión medida en la unidad configurada antes de guardar."); return; }
    if (point.photoRequired && !draft.evidenceId) { setError("Este punto requiere una foto real subida. Sigue pendiente hasta que la subas y guardes el punto."); return; }
    if (point.measurementType === "pressure" && draft.measurementValue !== "" && ((point.minValue != null && draft.measurementValue < point.minValue) || (point.maxValue != null && draft.measurementValue > point.maxValue)) && draft.result !== "hallazgo") { setError("La lectura está fuera de los límites aprobados. Registra un hallazgo con su explicación."); return; }
    if (draft.result === "pendiente") { setError("Selecciona un resultado para este punto."); return; }
    if (["hallazgo", "no_aplica"].includes(draft.result) && !draft.notes.trim()) { setError("Describe el hallazgo o explica por qué no aplica."); return; }
    if ((point.evidencePolicy === "always" || point.evidencePolicy === "findings" && draft.result === "hallazgo") && !draft.evidence.trim() && !draft.evidenceId) { setError("Este punto requiere evidencia antes de guardarlo."); return; }
    const id = execution!.id;
    await mutation(`save:${point.id}`, async () => {
      await request(`/api/rondas/executions/${id}/action`, { action: "save", expectedRevision: execution!.revision, pointId: point.id, ...draft, measurementValue: draft.measurementValue === "" ? null : draft.measurementValue });
      const next = { ...drafts }; delete next[point.id]; setDrafts(next);
      try { sessionStorage.setItem(storageKey(id), JSON.stringify(next)); } catch { /* beforeunload still guards */ }
      await loadDetail(id, false);
      setNotice(`Punto guardado por ${user.nombre}. La hora oficial aparece en el registro del punto.`);
    });
  }
  async function uploadPhoto(point: Point, file: File) {
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type)) { setError("Usa una imagen JPEG, PNG o WebP."); return; }
    if (file.size > 10 * 1024 * 1024) { setError("La foto supera 10 MB. Selecciona una imagen más pequeña."); return; }
    await mutation(`upload:${point.id}`, async () => {
      const form = new FormData(); form.set("executionId", String(execution!.id)); form.set("pointId", point.id); form.set("file", file);
      const response = await fetch("/api/rondas/evidence", { method: "POST", credentials: "same-origin", body: form });
      const data: any = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.error || "No se pudo subir la foto. La respuesta permanece sin enviar; vuelve a intentarlo.");
      updateDraft(point, { evidenceId: data.id });
      setNotice(`Foto subida para «${point.label}». Guarda este punto para confirmar la inspección y la medición.`);
    });
  }
  async function runAction(action: string) {
    if (!execution) return;
    if (dirty) { setError("Guarda tus cambios antes de cambiar el estado de la ronda."); return; }
    await mutation(action, async () => {
      await request(`/api/rondas/executions/${execution.id}/action`, { action, expectedRevision: execution.revision, reason: actionReason, ...(action === "reschedule" ? { dueAt: new Date(newDue).toISOString() } : {}) });
      setActionDialog(null); setActionReason(""); await loadDetail(execution.id, false); await loadList();
      setNotice(action === "submit" ? "Ronda enviada. Está pendiente de validación independiente; las OT conservan su estado." : `${label(action)}. El historial conserva autor, fecha y motivo.`);
    });
  }
  const zones = catalog.zones || [];
  const locationsOf = (scope: { locations?: ScopeLocation[]; locationId?: number | null; location_id?: number }) => scope.locations?.length ? scope.locations : scope.locationId || scope.location_id ? [{ id: (scope.locationId || scope.location_id)!, nombre: nameOf(catalog.locations, scope.locationId || scope.location_id) }] : [];
  const zoneNameOf = (scope: { zoneName?: string; zone_name?: string }) => scope.zoneName || scope.zone_name;
  const scopeDescription = (scope: { zoneName?: string; zone_name?: string; locations?: ScopeLocation[]; locationId?: number | null; location_id?: number }) => zoneNameOf(scope) ? `${zoneNameOf(scope)} · ${locationsOf(scope).length} ubicaciones` : locationsOf(scope).map(item => item.nombre).join(", ") || "Sin ubicación";
  const filtered = executions.filter(row => (!filter.site || String(row.site_id) === filter.site) && (!filter.zone || locationsOf(row).some(item => String(item.id) === filter.zone)) && (!filter.zoneId || String(row.zoneId || row.zone_id) === filter.zoneId) && (!filter.status || row.status === filter.status || row.temporalStatus === filter.status) && (!filter.mine || [row.owner_id, row.backup_id, row.reviewer_id, row.reviewer_backup_id].includes(user.id)));
  const statusOptions = [...new Set([...executions.map(row => row.status), ...executions.map(row => row.temporalStatus).filter(Boolean)])] as string[];
  const groups = useMemo(() => detail ? [...new Set(detail.points.map(point => point.group || "General"))] : [], [detail]);
  const pointLocations = useMemo(() => detail ? [...new Map(detail.points.filter(point => point.locationId).map(point => [point.locationId!, { id: point.locationId!, nombre: point.locationName || nameOf(catalog.locations, point.locationId) }])).values()] : [], [detail, catalog.locations]);
  const pointLocationOrder = new Map(detail ? locationsOf(detail.execution).map((item, index) => [item.id, index]) : []);
  const visiblePoints = detail?.points.filter(point => (!onlyPending || point.result === "pendiente") && (!pointGroup || (point.group || "General") === pointGroup) && (!pointLocation || String(point.locationId) === pointLocation)).sort((first, second) => {
    return (pointLocationOrder.get(first.locationId || detail.execution.location_id) ?? 0) - (pointLocationOrder.get(second.locationId || detail.execution.location_id) ?? 0);
  }) || [];
  const linkedIds = [...new Set(detail?.points.map(point => point.order_id).filter(Boolean) || [])];
  const openOrders = detail?.linkedOrders?.filter(order => !["cerrada", "verificada", "cancelada"].includes(order.estado));

  function startTemplate(template?: Template) {
    const defaultPoints: PointConfig[] = catalog.groups.flatMap(group => group.points.map(point => ({ ...point, group: group.code, active: true, exclusionReason: "", frequency: "diaria" as Frequency, firstDate: today(), evidencePolicy: "findings" as const, assetId: null, measurementType: "none" as const, measurementUnit: "", photoRequired: false, limitSource: "" })));
    const config: TemplateConfig = template ? { ...template.config, name: template.name, effectiveFrom: today(), reason: "", notifications: template.config.notifications || { recipientIds: [], events: [] } } : { effectiveFrom: today(), name: "", siteId: null, locationId: null, zoneId: null, shift: "Diurno", timezoneOffset: "-06:00", time: "08:00", windowMinutes: 60, ownerId: null, backupId: null, reviewerId: null, reviewerBackupId: null, reason: "", points: defaultPoints, notifications: { recipientIds: [], events: [] } };
    setEditorScope(template ? template.config.zoneId ? "zone" : "location" : zones.some(zone => zone.locations.length) ? "zone" : "location");
    setEditor({ template, config }); setEditorDirty(false); setError(""); setNotice("");
  }
  function editConfig(update: Partial<TemplateConfig>) { setEditor(previous => previous && { ...previous, config: { ...previous.config, ...update } }); setEditorDirty(true); }
  function editPoint(code: string, update: Partial<PointConfig>) { if (editor) editConfig({ points: editor.config.points.map(point => point.code === code ? { ...point, ...update } : point) }); }
  function closeEditor() { if (!editorDirty || window.confirm("¿Descartar los cambios de esta plantilla? Aún no se creó una versión.")) { setEditor(null); setEditorDirty(false); } }
  function changeScope(update: Partial<TemplateConfig>) {
    if (!editor) return;
    const config = { ...editor.config, ...update };
    const members = config.zoneId ? config.locations || [] : locationsOf({ locationId: config.locationId });
    const points = config.points.map(point => {
      const locationId = config.zoneId ? members.some(item => item.id === point.locationId) ? point.locationId : null : undefined;
      const asset = catalog.assets.find(item => item.id === point.assetId);
      const assetLocation = config.zoneId ? locationId : config.locationId;
      return { ...point, locationId, assetId: asset && assetLocation && asset.ubicacionId === assetLocation ? point.assetId : null };
    });
    editConfig({ ...update, points });
  }
  function chooseZone(id: number | null) {
    const zone = zones.find(item => item.id === id);
    changeScope({ zoneId: zone?.id || null, zoneName: zone?.name, zoneVersion: zone?.version, locations: zone?.locations.map(item => ({ id: item.id, nombre: item.nombre })), locationId: zone?.locations[0]?.id || null });
  }
  function startZone(zone?: Zone) { setZoneEditor({ zone, name: zone?.name || "", siteId: zone?.siteId || null, locationIds: zone?.locations.map(item => item.id) || [], reason: "" }); setZoneEditorDirty(false); setError(""); setNotice(""); }
  function editZone(update: Partial<ZoneEditor>) { setZoneEditor(previous => previous && { ...previous, ...update }); setZoneEditorDirty(true); }
  function closeZoneEditor() { if (!zoneEditorDirty || window.confirm("¿Descartar los cambios de la zona? Aún no se guardaron.")) { setZoneEditor(null); setZoneEditorDirty(false); } }
  function moveZoneMember(index: number, direction: number) {
    if (!zoneEditor) return;
    const members = [...zoneEditor.locationIds], target = index + direction;
    if (target < 0 || target >= members.length) return;
    [members[index], members[target]] = [members[target], members[index]]; editZone({ locationIds: members });
  }
  const editorLocations = editor ? editor.config.zoneId ? editor.config.locations || [] : locationsOf(editor.config) : [];
  const expandedControls = editor ? editor.config.points.filter(point => point.active).reduce((total, point) => total + (editor.config.zoneId && !point.locationId ? editorLocations.length : 1), 0) : 0;
  const currentEditorZone = zones.find(item => item.id === editor?.config.zoneId);
  const zoneChanged = !!editor?.config.zoneId && !!currentEditorZone && (currentEditorZone.version !== editor.config.zoneVersion || JSON.stringify(currentEditorZone.locations.map(item => item.id)) !== JSON.stringify(editorLocations.map(item => item.id)));

  return <div className="mx-auto max-w-6xl pb-16">
    <header className="mb-6 flex flex-wrap items-start justify-between gap-4">
      <div><p className="mb-1 text-xs font-semibold uppercase tracking-widest text-emerald-700">Mantenimiento · inspección en sitio</p><h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">Rondas de mantenimiento</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">Observa cada punto, registra el resultado y envía la ronda a validación.</p></div>
      <div className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs text-slate-600"><strong className="block text-slate-800">{user.nombre}</strong>{label(user.rol)} · horas en tu zona local</div>
    </header>
    {error && <div role="alert" className="mb-4 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><strong className="block">No se completó la operación</strong><p className="mt-1 whitespace-pre-wrap">{error}</p><button type="button" className="mt-3 underline" disabled={!!busy} onClick={() => { if (execution) void loadDetail(execution.id); else { setLoading(true); Promise.all([loadList(), request<Catalog>("/api/rondas/catalog").then(setCatalog)]).then(() => setError("")).catch(err => setError(err.message)).finally(() => setLoading(false)); } }}>Actualizar datos conservando borradores</button></div>}
    {notice && <div role="status" className="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900">{notice}</div>}
    {loading ? <div className="card p-8" role="status">Cargando rondas y catálogo…</div> : detailLoading ? <div className="card p-8" role="status">Cargando la ronda…</div> : detail ? <>
      <button type="button" className="btn-secondary mb-4 min-h-11" onClick={backToPanel} disabled={!!busy}>← Volver a rondas</button>
      <section className="card p-4 sm:p-6">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs text-slate-500">Ronda #{execution!.id} · plantilla v{execution!.template_version} · {execution!.scheduled_date}</p><h2 className="mt-1 text-xl font-semibold">{execution!.name}</h2><p className="mt-2 text-sm text-slate-600">{nameOf(catalog.sites, execution!.site_id)} · {scopeDescription(execution!)} · {execution!.shift}</p></div><div className="flex flex-wrap gap-2"><Badge value={execution!.status}/>{execution!.temporalStatus && <Badge value={execution!.temporalStatus}/>}</div></div>
        {zoneNameOf(execution!) && <div className="mt-3"><p className="text-xs font-semibold text-slate-500">Ubicaciones de esta ronda · alcance guardado</p><ol className="mt-2 flex flex-wrap gap-2">{locationsOf(execution!).map((item, index) => <li key={item.id} className="rounded-lg bg-slate-100 px-3 py-2 text-xs">{index + 1}. {item.nombre}</li>)}</ol><p className="mt-2 text-xs text-slate-500">Cada ubicación tiene sus propios registros. Un resultado no completa las demás ubicaciones.</p></div>}
        <dl className="mt-5 grid grid-cols-1 gap-3 text-sm sm:grid-cols-3"><div><dt className="text-slate-500">Responsable / suplente</dt><dd>{nameOf(catalog.users, execution!.owner_id)} / {nameOf(catalog.users, execution!.backup_id)}</dd></div><div><dt className="text-slate-500">Validador / suplente</dt><dd>{nameOf(catalog.users, execution!.reviewer_id)} / {nameOf(catalog.users, execution!.reviewer_backup_id)}</dd></div><div><dt className="text-slate-500">Límite de ejecución</dt><dd>{date(execution!.due_at)}</dd>{execution!.original_due_at !== execution!.due_at && <dd className="text-xs text-amber-800">Original: {date(execution!.original_due_at)}</dd>}</div></dl>
        {execution!.executed_at && <p className="mt-3 text-xs text-slate-500">Enviada por {nameOf(catalog.users, execution!.executed_by)} · {date(execution!.executed_at)}</p>}
        {execution!.reviewed_at && <p className="mt-1 text-xs text-slate-500">Revisión por {nameOf(catalog.users, execution!.reviewed_by)} · {date(execution!.reviewed_at)}</p>}
        {execution!.status === "validada" && <div className="mt-4 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm"><strong>Validada · {openOrders ? `${openOrders.length} acciones abiertas` : `${linkedIds.length} OT vinculadas`}</strong><p className="mt-1">La validación de la ronda no resuelve hallazgos ni cierra órdenes. Cada OT mantiene su seguimiento.</p></div>}
        {execution!.status === "devuelta" && <div className="mt-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><strong>Devuelta para corregir</strong><p className="mt-1 whitespace-pre-wrap">{returned ? formatDetails(returned.details) : "Consulta las observaciones del historial."}</p></div>}
      </section>
      <section className="sticky top-0 z-10 my-4 rounded-xl border border-slate-200 bg-white/95 p-4 shadow-sm backdrop-blur">
        <div className="flex items-center justify-between gap-3 text-sm"><strong>{answered} de {detail.points.length} puntos guardados</strong><span>{pending} pendientes</span></div><progress className="mt-2 h-2 w-full accent-emerald-700" value={answered} max={detail.points.length || 1} aria-label="Puntos guardados"/>
        <div className="mt-2 flex flex-wrap items-center justify-between gap-3"><label className="flex min-h-9 items-center gap-2 text-sm"><input type="checkbox" className="h-4 w-4 accent-emerald-700" checked={onlyPending} onChange={event => setOnlyPending(event.target.checked)}/>Solo puntos pendientes</label>{groups.length > 1 && <select aria-label="Grupo de puntos" className="input max-w-xs" value={pointGroup} onChange={event => setPointGroup(event.target.value)}><option value="">Todos los grupos</option>{groups.map(group => <option key={group} value={group}>{catalog.groups.find(item => item.code === group)?.name || group}</option>)}</select>}{pointLocations.length > 1 && <select aria-label="Ubicación de los puntos" className="input max-w-xs" value={pointLocation} onChange={event => setPointLocation(event.target.value)}><option value="">Todas las ubicaciones</option>{pointLocations.map(item => <option key={item.id} value={item.id}>{item.nombre}</option>)}</select>}{dirty && <span className="text-xs font-semibold text-amber-800">Cambios sin enviar: guarda cada punto</span>}</div>
      </section>
      {!canEdit && <p className="mb-4 rounded-lg bg-slate-100 p-3 text-sm text-slate-600">{["pendiente_validacion", "validada", "omitida"].includes(execution!.status) ? "Inspección en modo lectura por su estado actual." : "Solo el responsable o su suplente asignado puede registrar esta inspección."}</p>}
      <div className="space-y-4">{visiblePoints.map((point, index) => {
        const draft = drafts[point.id] || pointDraft(point);
        const changed = JSON.stringify(draft) !== JSON.stringify(pointDraft(point));
        const evidenceRequired = point.evidencePolicy === "always" || point.evidencePolicy === "findings" && draft.result === "hallazgo";
        return <article key={point.id} className={`card overflow-hidden ${draft.result === "hallazgo" ? "border-amber-300" : ""}`}>
          <div className="border-b border-slate-100 p-4 sm:p-5"><div className="flex items-start justify-between gap-3"><div><p className="mb-1 text-xs text-slate-500">{point.code} · {catalog.groups.find(group => group.code === point.group)?.name || point.group || "Inspección"}</p><h3 className="font-semibold">{point.label}</h3>{point.locationId && <p className="mt-1 text-sm font-semibold text-emerald-800">{point.locationName || nameOf(catalog.locations, point.locationId)}</p>}</div><Badge value={point.result}/></div><p className="mt-2 whitespace-pre-wrap text-sm text-slate-600">{point.criterion}</p>{point.assetId && <a href={`/activos/${point.assetId}`} className="mt-2 inline-block text-xs text-emerald-800 underline">Equipo vinculado: {nameOf(catalog.assets, point.assetId)}</a>}</div>
          <div className="p-4 sm:p-5"><fieldset disabled={!canEdit || !!busy}><legend className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Condición observada ahora</legend><div className="grid grid-cols-1 gap-2 sm:grid-cols-3">{(["conforme", "hallazgo", "no_aplica"] as Result[]).map(result => <label key={result} className={`flex min-h-12 cursor-pointer items-center gap-2 rounded-lg border px-3 py-3 text-sm ${draft.result === result ? result === "hallazgo" ? "border-amber-500 bg-amber-50 text-amber-900" : "border-emerald-600 bg-emerald-50 text-emerald-900" : "border-slate-300"} ${!canEdit ? "cursor-default" : ""}`}><input type="radio" className="h-4 w-4 accent-emerald-700" name={`point-${point.id}`} value={result} checked={draft.result === result} disabled={result === "no_aplica" && (point.mandatory || point.measurementType === "pressure" || point.photoRequired)} onChange={() => updateDraft(point, { result })}/>{label(result)}{result === "no_aplica" && (point.mandatory || point.measurementType === "pressure" || point.photoRequired) && " (control obligatorio)"}</label>)}</div>
            {draft.result === "hallazgo" && <p role="note" className="mt-3 rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm font-medium text-amber-900">Si hay riesgo inmediato, avisa al responsable y activa el protocolo del hospital sin esperar la validación.</p>}
            {(point.measurementType === "pressure" || point.photoRequired) && <div className="mt-4 rounded-xl border border-sky-200 bg-sky-50 p-4"><h4 className="mb-3 text-sm font-semibold">Medición y respaldo del punto</h4>{point.measurementType === "pressure" && <Field label={`Presión medida (${point.measurementUnit || "unidad no configurada"}) *`}><input type="number" step="any" inputMode="decimal" className="input min-h-11" value={draft.measurementValue} onChange={event => { const value = event.target.value === "" ? "" : Number(event.target.value); updateDraft(point, { measurementValue: value, ...(point.photoRequired && point.measurementValue != null && value !== point.measurementValue ? { evidenceId: null } : {}) }); }}/></Field>}{(point.minValue != null || point.maxValue != null) && <p className="mt-2 text-xs text-slate-600">Límites configurados: {point.minValue ?? "sin mínimo"} a {point.maxValue ?? "sin máximo"} {point.measurementUnit}. Fuente: {point.limitSource || "sin fuente"}. No sustituyen el criterio de inspección.</p>}{point.photoRequired && <div className="mt-3"><Field label="Foto de respaldo obligatoria *" hint="Fotografía solo el equipo, lectura o indicador. Evita pacientes, personas, pantallas clínicas y datos identificables."><input className="input min-h-11 bg-white" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={event => { const file = event.target.files?.[0]; event.target.value = ""; if (file) void uploadPhoto(point, file); }}/></Field><p className="mt-2 text-xs font-semibold text-sky-900">{busy === `upload:${point.id}` ? "Subiendo foto…" : draft.evidenceId ? "Foto subida. Guarda el punto para registrar esta respuesta." : "Sin foto: el punto sigue pendiente, aunque selecciones Conforme."}</p></div>}{draft.evidenceId && <a className="mt-3 inline-block text-sm text-emerald-800 underline" href={`/api/rondas/evidence?id=${draft.evidenceId}`} target="_blank" rel="noreferrer">Ver foto #{draft.evidenceId}</a>}</div>}
            <div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label={draft.result === "no_aplica" ? "Motivo por el que no aplica *" : draft.result === "hallazgo" ? "Describe el hallazgo *" : "Observaciones (opcional)"}><textarea className="input min-h-24" maxLength={4000} value={draft.notes} onChange={event => updateDraft(point, { notes: event.target.value })} placeholder="Qué observaste, dónde y con qué consecuencia"/></Field><Field label={`Evidencia${evidenceRequired ? " *" : " (opcional)"}`} hint="Describe la evidencia verificable o pega una ruta interna de un adjunto existente. No se suben archivos desde este campo."><textarea className="input min-h-24" maxLength={2000} value={draft.evidence} onChange={event => updateDraft(point, { evidence: event.target.value })} placeholder="Medición, referencia o /api/adjuntos/123"/></Field></div>
          </fieldset>
          <div className="mt-4 flex flex-wrap items-center justify-between gap-3"><div className="text-xs text-slate-500">{point.observed_at ? <>Guardado por <strong>{nameOf(catalog.users, point.observed_by)}</strong><br/>{date(point.observed_at)}</> : "Aún sin respuesta guardada"}{changed && <span className="mt-1 block font-semibold text-amber-800">Modificado: todavía no enviado</span>}</div>{canEdit && <button type="button" disabled={!!busy || draft.result === "pendiente" || !changed && !!point.observed_at} className="btn-primary min-h-11" onClick={() => void savePoint(point)}>{busy === `save:${point.id}` ? "Guardando…" : "Guardar este punto"}</button>}</div>
          {!canEdit && point.evidence && <div className="mt-3 text-sm"><EvidenceView value={point.evidence}/></div>}
          <div className="mt-4 flex flex-wrap items-center gap-3 border-t border-slate-100 pt-3">{point.order_id && <a href={`/ordenes/${point.order_id}`} className="text-sm font-semibold text-emerald-800 underline">Ver OT #{point.order_id}{detail.linkedOrders?.find(order => order.id === point.order_id)?.estado ? ` · ${label(detail.linkedOrders.find(order => order.id === point.order_id)!.estado)}` : " · consultar seguimiento"}</a>}{canEdit && point.result !== "pendiente" && !point.order_id && <button type="button" className="btn-secondary min-h-11 text-xs" disabled={!!busy || changed} onClick={() => setOrderDialog({ pointId: point.id, kind: "", reason: "", existingOrderId: "", planId: "" })}>Solicitar acción</button>}</div>
        </div></article>;
      })}{!visiblePoints.length && <div className="card p-6 text-sm text-slate-500">No hay puntos con estos filtros.</div>}</div>
      <section className="card mt-5 p-4 sm:p-6"><h2 className="text-lg font-semibold">Historial preventivo de equipos</h2><p className="mt-1 text-sm text-slate-600">Consulta separada de la inspección actual. Un equipo puede estar conforme hoy y tener mantenimiento preventivo vencido. La falta de evidencia no significa que nunca se haya realizado.</p>{detail.equipment.length ? <div className="mt-4 space-y-4">{detail.equipment.map(asset => <div className="rounded-xl border border-slate-200 p-4" key={asset.id}><a className="font-semibold text-emerald-800 underline" href={`/activos/${asset.id}`}>{asset.codigo} · {asset.nombre}</a><p className="mt-1 text-xs text-slate-500">{asset.ubicacionNombre} {asset.capturedAt && `· Datos consultados ${date(asset.capturedAt)}`}</p>{!asset.planes?.length ? <p className="mt-3 text-sm text-amber-800">Sin plan preventivo asociado. No se puede determinar la vigencia del mantenimiento.</p> : <div className="mt-3 space-y-3">{asset.planes.map(plan => <PlanHistory key={plan.id} plan={plan} users={catalog.users}/>)}</div>}</div>)}</div> : <p className="mt-4 rounded-lg bg-slate-50 p-4 text-sm text-slate-500">No hay equipos vinculados con historial disponible para esta ronda. No se infiere un estado de mantenimiento.</p>}</section>
      <section className="card mt-5 p-4 sm:p-6"><h2 className="text-lg font-semibold">Solicitudes y órdenes de seguimiento</h2><p className="mt-1 text-sm text-slate-600">Jefatura aprueba y programa cada solicitud aquí. Un hallazgo o un PM vencido con evidencia genera una solicitud al guardar el punto; aún no constituye una OT ni un mantenimiento realizado.</p><div className="mt-4 space-y-4">{(detail.proposals || []).map(proposal => <ProposalCard key={proposal.id} proposal={proposal} point={detail.points.find(point => point.id === proposal.point_id)} catalog={catalog} canApprove={admin} busy={!!busy} candidates={candidates?.proposalId === proposal.id ? candidates.orders : []} onDecision={body => mutation(`proposal:${proposal.id}`, async () => { const result = await request<{ orderId?: number }>(`/api/rondas/proposals/${proposal.id}/decision`, body); setCandidates(null); await loadDetail(execution!.id, false); setNotice(result.orderId ? `Solicitud aprobada y programada en OT #${result.orderId}. La orden conserva su ciclo de ejecución y validación.` : "Decisión guardada en la solicitud."); })}/>)}{!detail.proposals?.length && <p className="text-sm text-slate-500">Sin solicitudes registradas para esta ronda.</p>}</div>{!!detail.linkedOrders?.length && <div className="mt-4 border-t border-slate-200 pt-4"><h3 className="mb-2 text-sm font-semibold">Estado actual de las OT vinculadas</h3><ul className="space-y-2">{detail.linkedOrders.map(order => <li key={order.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-50 p-3 text-sm"><a className="text-emerald-800 underline" href={`/ordenes/${order.id}`}>OT #{order.id} · {order.titulo || label(order.tipo)}</a><Badge value={order.estado}/></li>)}</ul></div>}</section>
      <section className="card mt-5 p-4 sm:p-6"><h2 className="text-lg font-semibold">Cierre de inspección</h2><p className="mt-1 text-sm text-slate-600">Enviar deja la ronda pendiente de validación. El validador debe ser independiente de quien realizó los registros.</p><div className="mt-4 flex flex-wrap gap-3">{canEdit && <button type="button" className="btn-primary min-h-12" disabled={!!busy || dirty || pending > 0 || detail.points.length === 0} onClick={() => void runAction("submit")}>{busy === "submit" ? "Enviando…" : "Enviar a validación"}</button>}{execution!.status === "pendiente_validacion" && independentlyReviewable && <><button type="button" className="btn-primary min-h-12" disabled={!!busy} onClick={() => { setActionDialog("approve"); setActionReason(""); }}>Validar ronda</button><button type="button" className="btn-secondary min-h-12" disabled={!!busy} onClick={() => { setActionDialog("return"); setActionReason(""); }}>Devolver con observaciones</button></>}{admin && !["validada", "omitida", "pendiente_validacion"].includes(execution!.status) && <><button type="button" className="btn-secondary min-h-12" disabled={!!busy || dirty} onClick={() => { setActionDialog("reschedule"); setActionReason(""); setNewDue(""); }}>Reprogramar</button><button type="button" className="btn-secondary min-h-12" disabled={!!busy || dirty} onClick={() => { setActionDialog("miss"); setActionReason(""); }}>Registrar omisión</button></>}</div>{canEdit && (pending > 0 || dirty) && <p className="mt-3 text-xs text-amber-800">Para enviar: responde y guarda todos los puntos. No se completan automáticamente.</p>}{isReviewer && !independentlyReviewable && <p className="mt-3 text-sm text-amber-800">Participaste en esta inspección; debe validarla otro revisor autorizado.</p>}{execution!.status === "pendiente_validacion" && !isReviewer && <p className="mt-3 text-sm text-slate-500">En espera del validador asignado o su suplente.</p>}</section>
      <section className="card mt-5 p-4 sm:p-6"><h2 className="text-lg font-semibold">Trazabilidad</h2><p className="mt-1 text-xs text-slate-500">Revisión del registro: {execution!.revision}. Las versiones anteriores de plantilla se conservan.</p><ol className="mt-4 space-y-4">{detail.events.map(event => <li className="border-l-2 border-emerald-200 pl-3" key={event.id}><div className="flex flex-wrap justify-between gap-2 text-sm"><strong>{label(event.action)}</strong><time className="text-xs text-slate-500">{date(event.created_at)}</time></div><p className="text-xs text-slate-600">{event.actor_name || nameOf(catalog.users, event.actor_id)}</p>{event.details != null && <p className="mt-1 whitespace-pre-wrap break-words text-xs text-slate-500">{formatDetails(event.details)}</p>}</li>)}</ol>{!detail.events.length && <p className="mt-3 text-sm text-slate-500">Sin eventos disponibles.</p>}</section>
      <details className="card mt-5 p-4"><summary className="cursor-pointer font-semibold">Notificaciones y simulación ({detail.notifications.length})</summary><p className="mt-3 text-sm text-slate-600">No se envían correos reales desde este módulo. Los intentos y errores visibles corresponden al registro de notificaciones.</p><ul className="mt-3 space-y-2">{detail.notifications.map(item => <li key={item.id} className="rounded-lg bg-slate-50 p-3 text-xs"><strong>{label(item.event)}</strong> · {nameOf(catalog.users, item.recipient_id)} · <Badge value={item.status}/><p className="mt-1">{date(item.created_at)} · intentos: {item.attempts}</p>{item.last_error && <p className="mt-1 text-red-700">{item.last_error}</p>}</li>)}</ul>{!detail.notifications.length && <p className="mt-3 text-sm text-slate-500">No hay notificaciones registradas.</p>}</details>
    </> : <>
      <div className="mb-5 flex flex-wrap gap-2"><button type="button" className={panel === "rounds" ? "btn-primary min-h-11" : "btn-secondary min-h-11"} onClick={() => setPanel("rounds")}>Rondas</button><button type="button" className={panel === "actions" ? "btn-primary min-h-11" : "btn-secondary min-h-11"} onClick={() => setPanel("actions")}>Acciones y OT</button>{admin && <><button type="button" className={panel === "zones" ? "btn-primary min-h-11" : "btn-secondary min-h-11"} onClick={() => setPanel("zones")}>Zonas</button><button type="button" className={panel === "templates" ? "btn-primary min-h-11" : "btn-secondary min-h-11"} onClick={() => setPanel("templates")}>Plantillas y programación</button></>}</div>
      {panel === "rounds" ? <>
        <div className="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4">{[{ title: "Asignadas a mí", value: executions.filter(row => [row.owner_id, row.backup_id].includes(user.id) && !["validada", "omitida"].includes(row.status)).length }, { title: "Por validar", value: executions.filter(row => row.status === "pendiente_validacion").length }, { title: "Devueltas", value: executions.filter(row => row.status === "devuelta").length }, { title: "Fuera de plazo", value: executions.filter(row => ["vencida", "vencido"].includes(row.temporalStatus || "")).length }].map(stat => <div key={stat.title} className="card p-4"><p className="text-xs text-slate-500">{stat.title}</p><strong className="mt-1 block text-2xl">{stat.value}</strong></div>)}</div>
        <div className="card mb-5 p-4"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Field label="Sede"><select className="input min-h-11" value={filter.site} onChange={event => setFilter({ ...filter, site: event.target.value, zone: "", zoneId: "" })}><option value="">Todas las sedes</option>{catalog.sites.map(site => <option key={site.id} value={site.id}>{site.nombre}</option>)}</select></Field><Field label="Zona de ronda"><select className="input min-h-11" value={filter.zoneId} onChange={event => setFilter({ ...filter, zoneId: event.target.value })}><option value="">Todas las zonas</option>{zones.filter(item => !filter.site || String(item.siteId) === filter.site).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Ubicación"><select className="input min-h-11" value={filter.zone} onChange={event => setFilter({ ...filter, zone: event.target.value })}><option value="">Todas las ubicaciones</option>{catalog.locations.filter(item => !filter.site || String(item.sucursalId) === filter.site).map(item => <option key={item.id} value={item.id}>{item.nombre}</option>)}</select></Field><Field label="Estado"><select className="input min-h-11" value={filter.status} onChange={event => setFilter({ ...filter, status: event.target.value })}><option value="">Todos los estados</option>{statusOptions.map(status => <option key={status} value={status}>{label(status)}</option>)}</select></Field></div><label className="mt-3 flex min-h-9 items-center gap-2 text-sm"><input className="h-4 w-4 accent-emerald-700" type="checkbox" checked={filter.mine} onChange={event => setFilter({ ...filter, mine: event.target.checked })}/>Solo mis asignaciones y validaciones</label></div>
        <div className="mb-3 flex items-center justify-between"><h2 className="font-semibold">{filtered.length} rondas</h2><button type="button" className="text-sm text-emerald-800 underline" disabled={!!busy} onClick={() => void mutation("refresh", loadList)}>Actualizar</button></div>
        <div className="grid gap-3 lg:grid-cols-2">{filtered.map(row => <button type="button" key={row.id} className="card min-h-40 p-4 text-left transition hover:border-emerald-500 focus:outline-none focus:ring-2 focus:ring-emerald-500 sm:p-5" onClick={() => openExecution(row.id)}><div className="flex flex-wrap items-center justify-between gap-2"><span className="text-xs text-slate-500">#{row.id} · {row.scheduled_date} · {row.shift}</span><Badge value={row.status}/></div><h3 className="mt-3 font-semibold">{row.name}</h3><p className="mt-1 text-sm text-slate-600">{nameOf(catalog.sites, row.site_id)} · {scopeDescription(row)}</p>{zoneNameOf(row) && <p className="mt-2 text-xs text-slate-500">{locationsOf(row).map(item => item.nombre).join(" · ")}</p>}<p className="mt-3 text-xs text-slate-500">Responsable: {nameOf(catalog.users, row.owner_id)}</p><div className="mt-2 flex flex-wrap items-center justify-between gap-2"><span className="text-xs text-slate-500">Límite: {date(row.due_at)}</span>{row.temporalStatus && <Badge value={row.temporalStatus}/>}<span className="text-sm font-semibold text-emerald-800">Abrir ronda →</span></div></button>)}</div>{!filtered.length && <div className="card p-8 text-center"><h3 className="font-semibold">No hay rondas con estos filtros</h3><p className="mt-2 text-sm text-slate-500">{executions.length ? "Prueba otra sede, zona o estado." : admin ? "Crea una plantilla y genera sus fechas para empezar." : "Cuando te asignen una ronda, aparecerá aquí."}</p></div>}
      </> : panel === "zones" && admin ? <section className="card p-4 sm:p-6">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">Zonas de ronda</h2><p className="mt-1 max-w-2xl text-sm text-slate-600">Agrupa varias ubicaciones de una misma sede y ordénalas para el recorrido. Cada ubicación pertenece a una sola zona.</p></div><button type="button" className="btn-primary min-h-11" disabled={!!busy} onClick={() => startZone()}>Nueva zona</button></div>
        <p className="mt-4 rounded-lg bg-slate-50 p-3 text-sm text-slate-600">Las ubicaciones existentes conservan sus equipos y mantenimiento preventivo. Crear una zona no genera rondas: después selecciónala en una plantilla y genera las fechas.</p>
        <div className="mt-4 space-y-3">{zones.map(zone => <article key={zone.id} className="rounded-xl border border-slate-200 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold">{zone.name}</h3><p className="mt-1 text-xs text-slate-500">{nameOf(catalog.sites, zone.siteId)} · v{zone.version} · {zone.locations.length} ubicaciones</p></div><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={() => startZone(zone)}>Editar zona</button></div>{!zone.locations.length && <p className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-900">Zona sin ubicaciones · no disponible para nuevas plantillas.</p>}<ol className="mt-3 flex flex-wrap gap-2">{zone.locations.map((item, index) => <li key={item.id} className="rounded-lg bg-slate-50 px-3 py-2 text-sm">{index + 1}. {item.nombre}</li>)}</ol></article>)}</div>
        {!zones.length && <div className="mt-4 rounded-xl border border-dashed border-slate-300 p-6"><h3 className="font-semibold">Aún no hay zonas</h3><p className="mt-2 text-sm text-slate-500">Crea tu primera zona seleccionando las ubicaciones que forman parte del recorrido.</p></div>}
      </section> : panel === "actions" ? <section className="card p-4 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">Acciones de mantenimiento</h2><p className="mt-1 text-sm text-slate-500">Seguimiento conjunto de todas las OT preventivas y las originadas en rondas. Una ronda validada puede mantener acciones abiertas.</p></div><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={() => void mutation("refresh", loadList)}>Actualizar</button></div><div className="mt-4"><Field label="Filtrar órdenes"><select className="input min-h-11 max-w-sm" value={actionFilter} onChange={event => setActionFilter(event.target.value)}><option value="open">Todas las abiertas</option><option value="pending">Pendientes / programadas</option><option value="progress">En proceso</option><option value="validation">Pendientes de validación</option><option value="overdue">Vencidas</option><option value="all">Todas, incluidas cerradas</option></select></Field></div><div className="mt-4 space-y-3">{managedOrders.filter(order => actionFilter === "all" || actionFilter === "overdue" ? actionFilter === "all" || order.overdue : actionFilter === "validation" ? order.estado === "completada" || order.managementStatus === "pendiente_validacion" : actionFilter === "progress" ? order.estado === "en_proceso" : actionFilter === "pending" ? ["abierta", "en_espera"].includes(order.estado) : !["cerrada", "cancelada"].includes(order.estado)).map(order => <a key={order.id} className="block rounded-xl border border-slate-200 p-4 hover:border-emerald-500" href={`/ordenes/${order.id}`}><div className="flex flex-wrap items-start justify-between gap-2"><h3 className="text-sm font-semibold">OT #{order.id} · {order.titulo}</h3><div className="flex flex-wrap gap-2"><Badge value={order.managementStatus || order.estado}/>{order.overdue && <Badge value="vencida"/>}</div></div><p className="mt-2 text-xs text-slate-500">{label(order.tipo)} · prioridad {label(order.prioridad)} · {order.assignedName || "Sin asignar"}</p><p className="mt-1 text-xs text-slate-500">Límite: {date(order.vencimiento)}</p></a>)}</div>{!managedOrders.length && <p className="mt-4 text-sm text-slate-500">No hay órdenes de seguimiento disponibles.</p>}</section> : <>
        <section className="card p-4 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">Plantillas versionadas</h2><p className="mt-1 text-sm text-slate-500">La frecuencia se configura por punto. Editar crea una nueva versión y no altera rondas previas.</p></div><button type="button" className="btn-primary min-h-11" onClick={() => startTemplate()}>Nueva plantilla</button></div><div className="mt-4 space-y-3">{templates.map(template => <div key={template.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 p-4"><div><h3 className="font-semibold">{template.name}</h3><p className="mt-1 text-xs text-slate-500">v{template.version} · {nameOf(catalog.sites, template.config.siteId)} · {scopeDescription(template.config)} · {template.config.points.filter(point => point.active).length} puntos activos</p>{template.config.zoneId && <p className="mt-2 text-xs text-slate-500">{locationsOf(template.config).map(item => item.nombre).join(" · ")}</p>}</div><button type="button" className="btn-secondary min-h-11" onClick={() => startTemplate(template)}>Editar nueva versión</button></div>)}</div>{!templates.length && <p className="mt-4 text-sm text-slate-500">Sin plantillas configuradas.</p>}</section>
        <form className="card mt-5 p-4 sm:p-6" onSubmit={event => { event.preventDefault(); void mutation("generate", async () => { const result = await request<{ executions: Execution[] }>("/api/rondas/generate", { templateId: Number(generation.templateId), dateFrom: generation.dateFrom, dateTo: generation.dateTo }); await loadList(); setNotice(`Programación procesada del ${generation.dateFrom} al ${generation.dateTo}. ${result.executions.length} rondas disponibles en el intervalo. Las fechas existentes no se duplican.`); }); }}><h2 className="text-lg font-semibold">Generar rondas</h2><p className="mt-1 text-sm text-slate-500">Máximo 31 días por intervalo. Solo se incluyen puntos activos que correspondan por frecuencia y fecha inicial.</p><fieldset disabled={!!busy} className="mt-4 grid gap-3 sm:grid-cols-3"><Field label="Plantilla"><select required className="input min-h-11" value={generation.templateId} onChange={event => setGeneration({ ...generation, templateId: event.target.value })}><option value="">Selecciona una plantilla</option>{templates.map(template => <option key={template.id} value={template.id}>{template.name} · v{template.version}</option>)}</select></Field><Field label="Desde"><input required type="date" className="input min-h-11" value={generation.dateFrom} onChange={event => setGeneration({ ...generation, dateFrom: event.target.value })}/></Field><Field label="Hasta"><input required type="date" className="input min-h-11" min={generation.dateFrom} value={generation.dateTo} onChange={event => setGeneration({ ...generation, dateTo: event.target.value })}/></Field></fieldset><button type="submit" className="btn-primary mt-4 min-h-11" disabled={!!busy || !templates.length}>{busy === "generate" ? "Generando…" : "Generar fechas"}</button></form>
      </>}
    </>}
    {zoneEditor && <Modal title={zoneEditor.zone ? `Editar zona ${zoneEditor.zone.name}` : "Nueva zona de ronda"} onClose={closeZoneEditor} busy={!!busy}>
      <form onSubmit={event => {
        event.preventDefault();
        if (!zoneEditor.locationIds.length && !zoneEditor.zone) { setError("Selecciona al menos una ubicación para crear la zona."); return; }
        void mutation("zone", async () => {
          await request(zoneEditor.zone ? `/api/rondas/zones/${zoneEditor.zone.id}/version` : "/api/rondas/zones", { name: zoneEditor.name, siteId: zoneEditor.siteId, locationIds: zoneEditor.locationIds, reason: zoneEditor.reason, ...(zoneEditor.zone ? { expectedVersion: zoneEditor.zone.version } : {}) });
          const data = await request<{ zones: Zone[] }>("/api/rondas/zones"); setCatalog(previous => ({ ...previous, zones: data.zones || [] }));
          const edited = !!zoneEditor.zone; setZoneEditor(null); setZoneEditorDirty(false);
          setNotice(edited ? "Zona guardada. Las plantillas y rondas anteriores conservan sus ubicaciones; crea una nueva versión de la plantilla para adoptar este recorrido." : "Zona creada. Ahora puedes seleccionarla en una plantilla de ronda.");
        });
      }}>
        <p className="mb-4 text-sm text-slate-600">Elige las ubicaciones existentes de una sede. La selección y su orden definen el recorrido; no se modifican sus equipos ni planes preventivos.</p>
        {error && <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}
        <fieldset disabled={!!busy} className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre de la zona *"><input className="input min-h-11" required minLength={3} maxLength={160} value={zoneEditor.name} onChange={event => editZone({ name: event.target.value })}/></Field><Field label="Sede de la zona *"><select className="input min-h-11" required value={zoneEditor.siteId || ""} onChange={event => editZone({ siteId: Number(event.target.value) || null, locationIds: [] })}><option value="">Seleccionar sede</option>{catalog.sites.map(site => <option key={site.id} value={site.id}>{site.nombre}</option>)}</select></Field></div>
          <fieldset className="rounded-xl border border-slate-200 p-4"><legend className="px-1 text-sm font-semibold">Ubicaciones de la zona{!zoneEditor.zone && " *"}</legend><p className="mb-3 text-xs text-slate-500">{zoneEditor.locationIds.length} seleccionadas · máximo 100. Las asignadas a otra zona no se pueden seleccionar.</p>{zoneEditor.zone && <p className="mb-3 text-xs text-slate-600">Quitar una ubicación la libera para asignarla a otra zona. Puedes dejar esta zona vacía; conservará su historial y no estará disponible para nuevas plantillas.</p>}<div className="max-h-72 space-y-1 overflow-y-auto">{catalog.locations.filter(item => item.sucursalId === zoneEditor.siteId).map(item => {
            const otherZone = zones.find(zone => zone.id !== zoneEditor.zone?.id && zone.locations.some(member => member.id === item.id));
            const selected = zoneEditor.locationIds.includes(item.id);
            return <label key={item.id} className={`flex min-h-11 items-center gap-3 rounded-lg px-2 py-2 text-sm ${otherZone ? "bg-slate-50 text-slate-400" : "text-slate-700"}`}><input type="checkbox" className="h-4 w-4 shrink-0 accent-emerald-700" checked={selected} disabled={!!otherZone || !selected && zoneEditor.locationIds.length >= 100} onChange={event => editZone({ locationIds: event.target.checked ? [...zoneEditor.locationIds, item.id] : zoneEditor.locationIds.filter(id => id !== item.id) })}/><span>{item.nombre}{otherZone && <span className="ml-2 text-xs">Asignada a {otherZone.name}</span>}</span></label>;
          })}</div>{!zoneEditor.siteId ? <p className="text-sm text-slate-500">Selecciona una sede para ver sus ubicaciones.</p> : !catalog.locations.some(item => item.sucursalId === zoneEditor.siteId) && <p className="text-sm text-slate-500">Esta sede aún no tiene ubicaciones. Créelas primero desde Ubicaciones.</p>}</fieldset>
          {!!zoneEditor.locationIds.length && <section aria-label="Orden del recorrido"><h3 className="text-sm font-semibold">Orden del recorrido</h3><ol className="mt-3 space-y-2">{zoneEditor.locationIds.map((id, index) => <li key={id} className="flex items-center justify-between gap-3 rounded-lg bg-slate-50 p-3"><span className="min-w-0 break-words text-sm">{index + 1}. {nameOf(catalog.locations, id)}</span><div className="flex shrink-0 gap-2"><button type="button" className="btn-secondary min-h-11 px-3" aria-label={`Subir ${nameOf(catalog.locations, id)} en el recorrido`} disabled={index === 0} onClick={() => moveZoneMember(index, -1)}>↑</button><button type="button" className="btn-secondary min-h-11 px-3" aria-label={`Bajar ${nameOf(catalog.locations, id)} en el recorrido`} disabled={index === zoneEditor.locationIds.length - 1} onClick={() => moveZoneMember(index, 1)}>↓</button></div></li>)}</ol></section>}
          {zoneEditor.zone && <p className="rounded-lg bg-amber-50 p-3 text-sm text-amber-900">Las rondas y versiones de plantilla existentes conservarán su recorrido original. Para usar estos cambios, guarda después una nueva versión de cada plantilla correspondiente.</p>}
          <Field label={zoneEditor.zone ? "Motivo del cambio *" : "Motivo de creación de la zona *"}><textarea className="input min-h-20" required minLength={3} maxLength={2000} value={zoneEditor.reason} onChange={event => editZone({ reason: event.target.value })}/></Field>
        </fieldset>
        <div className="mt-5 flex flex-wrap justify-end gap-3"><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={closeZoneEditor}>Cancelar</button><button type="submit" className="btn-primary min-h-11" disabled={!!busy || !zoneEditor.zone && !zoneEditor.locationIds.length}>{busy === "zone" ? "Guardando…" : zoneEditor.zone ? "Guardar nueva versión de zona" : "Crear zona"}</button></div>
      </form>
    </Modal>}
    {editor && <Modal title={editor.template ? `Nueva versión de ${editor.template.name}` : "Nueva plantilla de ronda"} onClose={closeEditor} busy={!!busy}>
      <form onInvalid={event => { let element = event.target as HTMLElement | null; while (element) { if (element instanceof HTMLDetailsElement) element.open = true; element = element.parentElement; } }} onSubmit={event => { event.preventDefault(); void mutation("template", async () => { const path = editor.template ? `/api/rondas/templates/${editor.template.id}/version` : "/api/rondas/templates"; await request(path, { ...editor.config, ...(editor.template ? { expectedVersion: editor.template.version } : {}) }); setEditor(null); setEditorDirty(false); await loadList(); setNotice("Plantilla guardada. Puedes generar las rondas desde programación."); }); }}>
        <p className="mb-4 text-sm text-slate-600">Configura responsables y puntos del catálogo. Los cambios se guardan como una versión inmutable con su motivo.</p>
        {error && <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}
        <fieldset disabled={!!busy}>
          <div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre de la ronda *"><input className="input min-h-11" required maxLength={160} value={editor.config.name} onChange={event => editConfig({ name: event.target.value })}/></Field><Field label="Vigente desde *" hint="Esta versión solo aplica desde esta fecha; no cambia las rondas anteriores."><input className="input min-h-11" type="date" required value={editor.config.effectiveFrom} onChange={event => editConfig({ effectiveFrom: event.target.value })}/></Field><Field label="Turno *"><input className="input min-h-11" required value={editor.config.shift} onChange={event => editConfig({ shift: event.target.value })}/></Field><Field label="Sede *"><select className="input min-h-11" required value={editor.config.siteId || ""} onChange={event => changeScope({ siteId: Number(event.target.value) || null, locationId: null, zoneId: null, zoneName: undefined, zoneVersion: undefined, locations: undefined })}><option value="">Seleccionar sede</option>{catalog.sites.map(site => <option key={site.id} value={site.id}>{site.nombre}</option>)}</select></Field><Field label="Alcance de la ronda"><select className="input min-h-11" value={editorScope} onChange={event => { setEditorScope(event.target.value as "zone" | "location"); changeScope({ zoneId: null, zoneName: undefined, zoneVersion: undefined, locations: undefined, locationId: null }); }}><option value="zone">Zona de ronda · varias ubicaciones</option><option value="location">Una ubicación</option></select></Field>{editorScope === "zone" ? <Field label="Zona de ronda *" hint="Crea y ordena las zonas desde la pestaña Zonas."><select className="input min-h-11" required value={editor.config.zoneId || ""} onChange={event => chooseZone(Number(event.target.value) || null)}><option value="">Seleccionar zona de ronda</option>{zones.filter(item => item.siteId === editor.config.siteId).map(item => <option key={item.id} value={item.id} disabled={!item.locations.length}>{item.name} · {item.locations.length ? `${item.locations.length} ubicaciones` : "sin ubicaciones: no disponible"}</option>)}</select></Field> : <Field label="Ubicación *"><select className="input min-h-11" required value={editor.config.locationId || ""} onChange={event => changeScope({ locationId: Number(event.target.value) || null })}><option value="">Seleccionar ubicación</option>{catalog.locations.filter(item => item.sucursalId === editor.config.siteId).map(item => <option key={item.id} value={item.id}>{item.nombre}</option>)}</select></Field>}<Field label="Hora programada *"><input className="input min-h-11" type="time" required value={editor.config.time} onChange={event => editConfig({ time: event.target.value })}/></Field><Field label="Zona horaria (desfase UTC) *" hint="Ejemplo: -06:00. La hora de la plantilla usa este desfase fijo."><input className="input min-h-11" required pattern="[+-](0[0-9]|1[0-4]):[0-5][0-9]" value={editor.config.timezoneOffset} onChange={event => editConfig({ timezoneOffset: event.target.value })}/></Field><Field label="Ventana de ejecución (minutos) *"><input className="input min-h-11" type="number" min="1" max="1440" required value={editor.config.windowMinutes} onChange={event => editConfig({ windowMinutes: Number(event.target.value) })}/></Field></div>
          {editorScope === "zone" && <div className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-4"><h3 className="text-sm font-semibold">Ubicaciones incluidas en esta versión</h3>{editorLocations.length ? <ol className="mt-2 space-y-1 text-sm">{editorLocations.map((item, index) => <li key={item.id}>{index + 1}. {item.nombre}</li>)}</ol> : <p className="mt-2 text-sm">Selecciona una sede y una zona. Si aún no hay zonas, créalas desde Zonas.</p>}<p className="mt-3 text-xs text-slate-600">Se conserva este alcance en la plantilla y en las rondas generadas. Cambiar una zona requiere una nueva versión de la plantilla para adoptarlo.</p>{zoneChanged && <div className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><p>La zona tiene una versión más reciente. Revisa sus ubicaciones antes de guardar esta nueva versión.</p>{currentEditorZone?.locations.length ? <button type="button" className="btn-secondary mt-3 min-h-11" onClick={() => chooseZone(editor.config.zoneId || null)}>Usar ubicaciones actuales de la zona</button> : <p className="mt-2">La zona ahora está vacía. Selecciona otra zona o una ubicación para esta nueva versión de plantilla.</p>}</div>}</div>}
          <h3 className="mb-3 mt-6 font-semibold">Asignación y revisión independiente</h3><div className="grid gap-4 sm:grid-cols-2">{([{ key: "ownerId", title: "Responsable *", required: true }, { key: "backupId", title: "Suplente del responsable", required: false }, { key: "reviewerId", title: "Validador *", required: true }, { key: "reviewerBackupId", title: "Suplente del validador", required: false }] as const).map(field => <Field key={field.key} label={field.title}><select className="input min-h-11" required={field.required} value={editor.config[field.key] || ""} onChange={event => editConfig({ [field.key]: Number(event.target.value) || null })}><option value="">Seleccionar persona</option>{catalog.users.filter(item => ["admin", "jefe", "tecnico"].includes(item.rol || "")).map(item => <option key={item.id} value={item.id}>{item.nombre} · {label(item.rol)}</option>)}</select></Field>)}</div>
          <div className="mb-3 mt-6"><h3 className="font-semibold">Puntos del catálogo</h3><p className="mt-1 text-sm text-slate-500">{editor.config.points.filter(point => point.active).length} activos de {editor.config.points.length}. Cada punto conserva criterio, frecuencia, evidencia y equipo opcional.</p><p className="mt-2 text-sm font-semibold text-emerald-800">{expandedControls} controles por fecha si todos corresponden por frecuencia{editor.config.zoneId ? ` · ${editorLocations.length} ubicaciones` : ""}.</p>{editor.config.zoneId && <p className="mt-1 text-xs text-slate-500">«Cada ubicación de la zona» crea un registro separado por ubicación. Para inspeccionar un equipo, elige su ubicación y después el equipo.</p>}{expandedControls > 1500 && <p role="alert" className="mt-2 text-sm text-red-700">El alcance supera 1500 controles. Divide los puntos entre varias plantillas antes de guardar.</p>}</div>
          <div className="space-y-3">{catalog.groups.map(group => {
            const groupPoints = editor.config.points.filter(point => point.group === group.code);
            return <details key={group.code} className="rounded-xl border border-slate-200"><summary className="cursor-pointer rounded-xl bg-slate-50 p-4 font-semibold">{group.name} <span className="text-xs font-normal text-slate-500">({groupPoints.filter(point => point.active).length}/{groupPoints.length} activos{groupPoints.some(point => point.active && !point.criterion.trim()) ? " · faltan criterios" : ""})</span></summary><div className="divide-y divide-slate-100">{groupPoints.map(point => <div key={point.code} className="p-4"><div className="flex flex-wrap items-center justify-between gap-2"><strong className="text-sm">{point.label}</strong><label className="flex min-h-10 items-center gap-2 text-sm"><input type="checkbox" className="h-4 w-4 accent-emerald-700" checked={point.active} disabled={point.mandatory} onChange={event => editPoint(point.code, { active: event.target.checked })}/>Activo</label></div><label className="mb-2 flex min-h-11 items-center gap-2 text-sm"><input className="h-4 w-4 accent-emerald-700" type="checkbox" checked={!!point.mandatory} onChange={event => editPoint(point.code, { mandatory: event.target.checked, ...(event.target.checked ? { active: true } : {}) })}/>Control obligatorio (no admite No aplica)</label><p className="mb-3 text-xs text-slate-400">{point.code}</p><div className="mb-3"><Field label="Nombre del punto *"><input className="input min-h-11" required maxLength={300} value={point.label} onChange={event => editPoint(point.code, { label: event.target.value })}/></Field></div>{!point.active && <Field label="Motivo de exclusión *"><input className="input mb-3" required maxLength={1000} value={point.exclusionReason} onChange={event => editPoint(point.code, { exclusionReason: event.target.value })}/></Field>}<div className="grid gap-3 sm:grid-cols-2"><Field label="Frecuencia"><select className="input min-h-11" value={point.frequency} onChange={event => editPoint(point.code, { frequency: event.target.value as Frequency })}>{FREQUENCIES.map(item => <option value={item} key={item}>{label(item)}</option>)}</select></Field><Field label="Primera fecha *"><input className="input min-h-11" type="date" required value={point.firstDate} onChange={event => editPoint(point.code, { firstDate: event.target.value })}/></Field><Field label="Evidencia requerida"><select className="input min-h-11" value={point.evidencePolicy} onChange={event => editPoint(point.code, { evidencePolicy: event.target.value as PointConfig["evidencePolicy"] })}><option value="none">Opcional</option><option value="findings">En hallazgos</option><option value="always">Siempre</option></select></Field>{editor.config.zoneId && <Field label="Aplicar este punto en" hint={!point.locationId ? `Un control independiente en cada una de las ${editorLocations.length} ubicaciones.` : "Un control en esta ubicación de la zona."}><select className="input min-h-11" value={point.locationId || ""} onChange={event => { const locationId = Number(event.target.value) || null; const asset = catalog.assets.find(item => item.id === point.assetId); editPoint(point.code, { locationId, assetId: asset && asset.ubicacionId === locationId ? point.assetId : null }); }}><option value="">Cada ubicación de la zona</option>{editorLocations.map(item => <option key={item.id} value={item.id}>{item.nombre}</option>)}</select></Field>}<Field label="Equipo vinculado (opcional)" hint={editor.config.zoneId && !point.locationId ? "Selecciona una ubicación concreta para vincular un equipo." : "Solo equipos de la ubicación seleccionada."}><select className="input min-h-11" disabled={!editor.config.locationId || !!editor.config.zoneId && !point.locationId} value={point.assetId || ""} onChange={event => editPoint(point.code, { assetId: Number(event.target.value) || null })}><option value="">Sin equipo: inspección de ubicación</option>{catalog.assets.filter(asset => asset.ubicacionId === (editor.config.zoneId ? point.locationId : editor.config.locationId)).map(asset => <option key={asset.id} value={asset.id}>{asset.codigo} · {asset.nombre}</option>)}</select></Field></div><div className="mt-3 rounded-lg bg-sky-50 p-3"><div className="grid gap-3 sm:grid-cols-2"><Field label="Medición requerida"><select className="input min-h-11" value={point.measurementType || "none"} onChange={event => editPoint(point.code, { measurementType: event.target.value as "none" | "pressure" })}><option value="none">Sin medición estructurada</option><option value="pressure">Presión</option></select></Field>{point.measurementType === "pressure" && <Field label="Unidad de presión *"><input required={point.active} className="input min-h-11" maxLength={30} value={point.measurementUnit || ""} placeholder="Unidad aprobada para este equipo" onChange={event => editPoint(point.code, { measurementUnit: event.target.value })}/></Field>}</div><label className="mt-2 flex min-h-11 items-center gap-2 text-sm"><input className="h-4 w-4 accent-emerald-700" type="checkbox" checked={!!point.photoRequired} onChange={event => editPoint(point.code, { photoRequired: event.target.checked })}/>Exigir foto del equipo o lectura antes de guardar</label>{point.measurementType === "pressure" && <details className="mt-2"><summary className="cursor-pointer text-sm">Límites aprobados (opcionales)</summary><p className="mt-2 text-xs text-slate-600">Introduce límites solo si dispones de una fuente aprobada para este equipo y esta zona.</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="Mínimo"><input className="input min-h-11" type="number" step="any" value={point.minValue ?? ""} onChange={event => editPoint(point.code, { minValue: event.target.value === "" ? undefined : Number(event.target.value) })}/></Field><Field label="Máximo"><input className="input min-h-11" type="number" step="any" value={point.maxValue ?? ""} onChange={event => editPoint(point.code, { maxValue: event.target.value === "" ? undefined : Number(event.target.value) })}/></Field></div><div className="mt-3"><Field label={point.minValue != null || point.maxValue != null ? "Fuente aprobada de los límites *" : "Fuente de los límites"}><input className="input min-h-11" maxLength={1000} required={point.minValue != null || point.maxValue != null} value={point.limitSource || ""} onChange={event => editPoint(point.code, { limitSource: event.target.value })}/></Field></div></details>}</div><div className="mt-3"><Field label={point.active ? "Criterio de inspección *" : "Criterio de inspección"}><textarea className="input min-h-20" required={point.active} minLength={point.active ? 3 : undefined} maxLength={2000} placeholder="Criterio aprobado para esta zona (sin límites clínicos inventados)" value={point.criterion} onChange={event => editPoint(point.code, { criterion: event.target.value })}/></Field></div></div>)}</div></details>;
          })}</div>
          <details className="mt-6 rounded-xl border border-slate-200 p-4"><summary className="cursor-pointer font-semibold">Notificaciones · solo simulación</summary><p className="mt-3 text-sm text-slate-600">Sin destinatarios ni eventos seleccionados por defecto. Esta configuración registra simulaciones, sin enviar correos reales.</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><fieldset><legend className="mb-2 text-sm font-semibold">Destinatarios</legend><div className="max-h-52 space-y-1 overflow-auto">{catalog.users.map(item => <label className="flex min-h-10 items-center gap-2 text-sm" key={item.id}><input type="checkbox" className="h-4 w-4 accent-emerald-700" checked={editor.config.notifications.recipientIds.includes(item.id)} onChange={event => editConfig({ notifications: { ...editor.config.notifications, recipientIds: event.target.checked ? [...editor.config.notifications.recipientIds, item.id] : editor.config.notifications.recipientIds.filter(id => id !== item.id) } })}/>{item.nombre}</label>)}</div></fieldset><fieldset><legend className="mb-2 text-sm font-semibold">Eventos</legend>{["asignada", "vencida", "pendiente_validacion", "devuelta", "validada", "omitida", "reprogramada"].map(item => <label className="flex min-h-10 items-center gap-2 text-sm" key={item}><input type="checkbox" className="h-4 w-4 accent-emerald-700" checked={editor.config.notifications.events.includes(item)} onChange={event => editConfig({ notifications: { ...editor.config.notifications, events: event.target.checked ? [...editor.config.notifications.events, item] : editor.config.notifications.events.filter(value => value !== item) } })}/>{label(item)}</label>)}</fieldset></div></details>
          <div className="mt-5"><Field label={editor.template ? "Motivo de la nueva versión *" : "Motivo de creación *"}><textarea className="input min-h-20" required minLength={3} maxLength={2000} value={editor.config.reason} onChange={event => editConfig({ reason: event.target.value })}/></Field></div>
        </fieldset><div className="mt-5 flex flex-wrap justify-end gap-3"><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={closeEditor}>Cancelar</button><button type="submit" className="btn-primary min-h-11" disabled={!!busy || expandedControls > 1500 || zoneChanged || editorScope === "zone" && !editorLocations.length}>{busy === "template" ? "Guardando…" : editor.template ? "Crear nueva versión" : "Crear plantilla"}</button></div>
      </form>
    </Modal>}
    {actionDialog && <Modal title={actionDialog === "approve" ? "Validar inspección" : actionDialog === "return" ? "Devolver para corrección" : actionDialog === "reschedule" ? "Reprogramar ronda" : "Registrar ronda omitida"} onClose={() => setActionDialog(null)} busy={!!busy}>
      <form onSubmit={event => { event.preventDefault(); void runAction(actionDialog); }}>{error && <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}<p className="mb-4 text-sm text-slate-600">{actionDialog === "approve" ? "Confirmas la revisión independiente de los registros y evidencias. La validación no cierra OT ni aprueba solicitudes de trabajo." : actionDialog === "reschedule" ? "Se conservará el vencimiento original y el motivo de reprogramación." : actionDialog === "miss" ? "La omisión quedará en el historial y no cuenta como inspección realizada." : "El responsable verá estas observaciones para corregir y volver a enviar."}</p><fieldset disabled={!!busy}>{actionDialog === "reschedule" && <div className="mb-4"><Field label="Nuevo límite de ejecución *" hint="Se interpreta en la zona horaria local de este navegador."><input className="input min-h-11" required type="datetime-local" value={newDue} onChange={event => setNewDue(event.target.value)}/></Field></div>}<Field label={actionDialog === "approve" ? "Comprobación de validación *" : "Motivo / observaciones *"}><textarea className="input min-h-28" required minLength={3} maxLength={4000} value={actionReason} onChange={event => setActionReason(event.target.value)}/></Field></fieldset><div className="mt-5 flex flex-wrap justify-end gap-3"><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={() => setActionDialog(null)}>Cancelar</button><button className="btn-primary min-h-11" type="submit" disabled={!!busy}>{busy ? "Guardando…" : "Confirmar"}</button></div></form>
    </Modal>}
    {orderDialog && <Modal title="Solicitar acción de mantenimiento" onClose={() => setOrderDialog(null)} busy={!!busy}>
      <form onSubmit={event => { event.preventDefault(); void mutation("order", async () => { const result = await request<{ proposalId: number; reused: boolean }>(`/api/rondas/executions/${execution!.id}/order`, { pointId: orderDialog.pointId, kind: orderDialog.kind, reason: orderDialog.reason, ...(orderDialog.planId ? { planId: Number(orderDialog.planId) } : {}), expectedRevision: execution!.revision }); setOrderDialog(null); await loadDetail(execution!.id, false); setNotice(`Solicitud #${result.proposalId} ${result.reused ? "ya registrada" : "creada"}. Queda pendiente de aprobación y programación de jefatura; aún no es una OT ejecutable.`); }); }}>
        {error && <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}<p className="mb-4 text-sm text-slate-600">La solicitud requiere aprobación de jefatura antes de generar una orden de trabajo. Distingue una falla observada de mantenimiento preventivo atrasado.</p><fieldset disabled={!!busy} className="space-y-4"><Field label="Tipo de acción *"><select required className="input min-h-11" value={orderDialog.kind} onChange={event => setOrderDialog({ ...orderDialog, kind: event.target.value, planId: "" })}><option value="">Seleccionar clasificación</option><option value="correctivo">Correctivo: falla actual observada</option><option value="preventivo">Preventivo: mantenimiento pendiente</option></select></Field>{orderDialog.kind === "preventivo" && <Field label="Plan preventivo relacionado *"><select required className="input min-h-11" value={orderDialog.planId} onChange={event => setOrderDialog({ ...orderDialog, planId: event.target.value })}><option value="">Selecciona el plan, si existe</option>{detail?.equipment.filter(asset => asset.id === detail.points.find(point => point.id === orderDialog.pointId)?.assetId).flatMap(asset => asset.planes.map(plan => <option key={plan.id} value={plan.id}>{asset.codigo} · {plan.titulo}</option>))}</select></Field>}<Field label="Justificación de necesidad y riesgo *" hint="Describe la condición observada, su impacto y la consecuencia de posponer. Jefatura define la prioridad y el plazo al aprobar."><textarea required className="input min-h-28" maxLength={4000} value={orderDialog.reason} onChange={event => setOrderDialog({ ...orderDialog, reason: event.target.value })}/></Field></fieldset><div className="mt-5 flex flex-wrap justify-end gap-3"><button type="button" className="btn-secondary min-h-11" disabled={!!busy} onClick={() => setOrderDialog(null)}>Cancelar</button><button type="submit" className="btn-primary min-h-11" disabled={!!busy}>{busy === "order" ? "Registrando…" : "Solicitar aprobación"}</button></div>
      </form>
    </Modal>}
  </div>;
}

function formatDetails(details: unknown): string {
  if (!details) return "";
  if (typeof details === "string") { try { return formatDetails(JSON.parse(details)); } catch { return details; } }
  if (Array.isArray(details)) return details.map(formatDetails).join(" · ");
  if (typeof details === "object") return Object.entries(details as Record<string, unknown>).map(([key, value]) => `${label(key)}: ${typeof value === "object" ? formatDetails(value) : String(value ?? "—")}`).join(" · ");
  return String(details);
}
function PlanHistory({ plan, users }: { plan: Plan; users: Entity[] }) {
  const verified = plan.lastVerifiedExecution;
  const status = plan.complianceStatus || (plan.evidenceStatus === "sin_evidencia" || !verified ? "sin_historial" : plan.overdue ? "vencido" : plan.nextDue ? "vigente" : "sin_config");
  return <div className="rounded-lg bg-slate-50 p-3">
    <div className="flex flex-wrap items-start justify-between gap-2"><h4 className="text-sm font-semibold">{plan.titulo}{plan.activo === false && " · plan inactivo"}</h4><div className="flex flex-wrap gap-2"><Badge value={status}/><Badge value={plan.managementStatus || "sin_ot"}/></div></div>
    <dl className="mt-3 grid grid-cols-2 gap-3 text-xs sm:grid-cols-4"><div><dt className="text-slate-500">Frecuencia real del plan</dt><dd className="mt-1 font-medium">{label(plan.frecuencia)}</dd></div><div><dt className="text-slate-500">Última ejecución verificada</dt><dd className="mt-1 font-medium">{verified ? date(verified.completadaEn) : "Sin evidencia verificada"}</dd></div><div><dt className="text-slate-500">Tiempo transcurrido</dt><dd className="mt-1 font-medium">{plan.daysElapsed == null ? "No determinable" : `${plan.daysElapsed} días`}</dd></div><div><dt className="text-slate-500">Próximo mantenimiento calculado</dt><dd className="mt-1 font-medium">{plan.nextDue || "Sin fecha verificable"}</dd></div></dl>
    <p className="mt-3 text-xs text-slate-500">Vigencia calculada con ejecución verificada + frecuencia del plan. Programar una OT no cambia esta vigencia.</p>
    {plan.scheduleDiscrepancy && <p className="mt-2 rounded-lg bg-amber-50 p-2 text-xs text-amber-900">El calendario guardado ({plan.configuredNextDue || "sin fecha"}) difiere de la fecha calculada. Requiere revisión del plan.</p>}
    {verified && <div className="mt-3 border-t border-slate-200 pt-3 text-xs"><a href={`/ordenes/${verified.id}`} className="text-emerald-800 underline">OT #{verified.id} verificada</a><p className="mt-1 text-slate-500">Validada por {verified.verificadorNombre || nameOf(users, verified.verificadoPor)} · {date(verified.verificadoEn)}</p><ul className="mt-2 space-y-1">{verified.evidence?.map(evidence => <li key={evidence.id}><a className="text-emerald-800 underline" href={safeEvidence(evidence.url) ? evidence.url : undefined} target="_blank" rel="noreferrer">{evidence.nombre}</a></li>)}</ul>{verified.trabajosRealizados && <p className="mt-2 whitespace-pre-wrap"><strong>Trabajo documentado:</strong> {verified.trabajosRealizados}</p>}{verified.verificacionNotas && <p className="mt-1 whitespace-pre-wrap"><strong>Verificación:</strong> {verified.verificacionNotas}</p>}{!verified.evidence?.length && !verified.trabajosRealizados && <p className="mt-1 text-slate-500">Evidencia documental: consulta la OT verificada.</p>}</div>}
    {plan.latestUnverifiedExecution && <p className="mt-3 text-xs text-amber-800">Existe <a className="underline" href={`/ordenes/${plan.latestUnverifiedExecution.id}`}>OT #{plan.latestUnverifiedExecution.id}</a> sin evidencia suficiente de verificación. No se toma como mantenimiento verificado.</p>}
    {!!plan.pendingOrders?.length && <div className="mt-3 border-t border-slate-200 pt-3"><p className="mb-2 text-xs font-semibold">Gestión de OT, independiente del cumplimiento</p><ul className="space-y-2">{plan.pendingOrders.map(order => <li key={order.id} className="flex flex-wrap justify-between gap-2 text-xs"><a className="text-emerald-800 underline" href={`/ordenes/${order.id}`}>#{order.id} · {order.titulo}</a><span>{label(order.estado)} · límite {date(order.vencimiento)}</span></li>)}</ul></div>}
  </div>;
}
function Modal({ title, children, onClose, busy }: { title: string; children: ReactNode; onClose: () => void; busy: boolean }) {
  const container = useRef<HTMLDivElement>(null);
  const latestClose = useRef(onClose); latestClose.current = onClose;
  const latestBusy = useRef(busy); latestBusy.current = busy;
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const oldOverflow = document.body.style.overflow; document.body.style.overflow = "hidden";
    container.current?.querySelector<HTMLElement>("button")?.focus();
    function keyboard(event: KeyboardEvent) {
      if (event.key === "Escape" && !latestBusy.current) { event.preventDefault(); latestClose.current(); }
      if (event.key === "Tab") {
        const elements = Array.from(container.current?.querySelectorAll<HTMLElement>('button:not(:disabled), [href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), summary, [tabindex="0"]') || []).filter(element => element.getClientRects().length > 0);
        const first = elements[0], last = elements[elements.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }
    }
    window.addEventListener("keydown", keyboard);
    return () => { document.body.style.overflow = oldOverflow; window.removeEventListener("keydown", keyboard); previous?.focus(); };
  }, []);
  return <div className="fixed inset-0 z-[110] flex items-end justify-center bg-slate-900/50 p-0 sm:items-center sm:p-5"><div ref={container} role="dialog" aria-modal="true" aria-label={title} className="max-h-[95dvh] w-full max-w-3xl overflow-y-auto rounded-t-2xl bg-white shadow-2xl sm:rounded-2xl"><header className="sticky top-0 z-10 flex items-center justify-between gap-4 border-b border-slate-200 bg-white p-4 sm:px-6"><h2 className="text-lg font-semibold">{title}</h2><button type="button" aria-label="Cerrar" className="btn-secondary min-h-11" onClick={onClose} disabled={busy}>Cerrar</button></header><div className="p-4 sm:p-6">{children}</div></div></div>;
}
function ProposalCard({ proposal, point, catalog, canApprove, busy, candidates, onDecision }: { proposal: Proposal; point?: Point; catalog: Catalog; canApprove: boolean; busy: boolean; candidates: CandidateOrder[]; onDecision: (body: Record<string, unknown>) => Promise<void> }) {
  const [priority, setPriority] = useState(proposal.priority || "");
  const [dueAt, setDueAt] = useState("");
  const [executorType, setExecutorType] = useState("internal");
  const [assignedTo, setAssignedTo] = useState("");
  const [providerId, setProviderId] = useState("");
  const [existingOrderId, setExistingOrderId] = useState("");
  const [reason, setReason] = useState("");
  const [decision, setDecision] = useState("approve");
  const [localError, setLocalError] = useState("");
  return <article className="rounded-xl border border-slate-200 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-semibold">Solicitud #{proposal.id} · {label(proposal.kind)}</h3><p className="mt-1 text-xs text-slate-500">{point?.label} · {date(proposal.created_at)}</p></div><Badge value={proposal.status}/></div><p className="mt-3 whitespace-pre-wrap text-sm text-slate-600">{proposal.reason}</p>{proposal.order_id && <a className="mt-3 inline-block text-sm font-semibold text-emerald-800 underline" href={`/ordenes/${proposal.order_id}`}>Ver OT #{proposal.order_id}</a>}{canApprove && ["pendiente_aprobacion", "devuelta"].includes(proposal.status) && <form className="mt-4 border-t border-slate-200 pt-4" onSubmit={event => {
    event.preventDefault(); setLocalError("");
    if (!reason.trim()) { setLocalError("Escribe la justificación de la decisión y su riesgo."); return; }
    if (decision === "approve" && (!priority || !dueAt || !assignedTo || executorType === "provider" && !providerId)) { setLocalError("Completa prioridad, fecha, responsable y proveedor cuando corresponda."); return; }
    void onDecision({ action: decision, reason, ...(decision === "approve" ? { priority, dueAt: new Date(dueAt).toISOString(), executorType, assignedTo: Number(assignedTo), ...(executorType === "provider" ? { providerId: Number(providerId) } : {}), ...(existingOrderId ? { existingOrderId: Number(existingOrderId) } : {}) } : {}) });
  }}><fieldset disabled={busy} className="space-y-3"><Field label="Decisión de jefatura"><select className="input min-h-11" value={decision} onChange={event => setDecision(event.target.value)}><option value="approve">Aprobar y programar</option><option value="return">Devolver para aclaración</option><option value="reject">Rechazar con motivo</option></select></Field>{decision === "approve" && <><div className="grid gap-3 sm:grid-cols-2"><Field label="Prioridad definitiva *"><select required className="input min-h-11" value={priority} onChange={event => setPriority(event.target.value)}><option value="">Seleccionar prioridad</option>{["baja", "media", "alta", "urgente"].map(item => <option value={item} key={item}>{label(item)}</option>)}</select></Field><Field label="Fecha y hora límite *" hint="Hora local de este navegador"><input className="input min-h-11" type="datetime-local" required value={dueAt} onChange={event => setDueAt(event.target.value)}/></Field><Field label="Ejecución"><select className="input min-h-11" value={executorType} onChange={event => setExecutorType(event.target.value)}><option value="internal">Equipo interno</option><option value="provider">Proveedor externo</option></select></Field><Field label={executorType === "provider" ? "Responsable interno / coordinador *" : "Ejecutor interno *"}><select className="input min-h-11" required value={assignedTo} onChange={event => setAssignedTo(event.target.value)}><option value="">Seleccionar persona</option>{catalog.users.filter(item => ["admin", "jefe", "tecnico"].includes(item.rol || "")).map(item => <option value={item.id} key={item.id}>{item.nombre}</option>)}</select></Field>{executorType === "provider" && <Field label="Proveedor *"><select className="input min-h-11" required value={providerId} onChange={event => setProviderId(event.target.value)}><option value="">Seleccionar proveedor</option>{(catalog.providers || []).map(item => <option value={item.id} key={item.id}>{item.nombre}</option>)}</select></Field>}</div>{candidates.length > 0 && <div className="rounded-lg border border-amber-300 bg-amber-50 p-3"><p className="mb-3 text-sm text-amber-900">Hay OT abiertas de este equipo y plan. Revisa cuál corresponde a este mismo ciclo preventivo antes de aprobar. No se creará una duplicada.</p><Field label="Confirmo la OT correspondiente al mismo ciclo"><select required className="input min-h-11" value={existingOrderId} onChange={event => setExistingOrderId(event.target.value)}><option value="">Revisar y seleccionar</option>{candidates.map(order => <option key={order.id} value={order.id}>#{order.id} · {order.titulo} · {label(order.estado)} · {date(order.vencimiento)}</option>)}</select></Field><div className="mt-2 flex flex-wrap gap-3">{candidates.map(order => <a className="text-xs text-emerald-800 underline" key={order.id} href={`/ordenes/${order.id}`} target="_blank" rel="noreferrer">Consultar OT #{order.id}</a>)}</div></div>}<details className="rounded-lg bg-slate-50 p-3"><summary className="cursor-pointer text-sm">Vincular una OT existente en lugar de crear otra</summary><div className="mt-3"><Field label="Número de OT existente" hint="La API verificará que la OT corresponda al equipo, tipo y seguimiento solicitado."><input className="input min-h-11" type="number" min="1" step="1" value={existingOrderId} onChange={event => setExistingOrderId(event.target.value)}/></Field></div></details></>}<Field label="Justificación de decisión y riesgo *"><textarea className="input min-h-20" required maxLength={4000} value={reason} onChange={event => setReason(event.target.value)} placeholder="Motivo de la prioridad y del plazo, o aclaración requerida"/></Field></fieldset>{localError && <p role="alert" className="mt-3 text-sm text-red-700">{localError}</p>}<button className="btn-primary mt-4 min-h-11" type="submit" disabled={busy}>{busy ? "Guardando…" : decision === "approve" ? "Aprobar y programar" : decision === "return" ? "Devolver solicitud" : "Rechazar solicitud"}</button><p className="mt-2 text-xs text-slate-500">No se envían mensajes ni se crean cuentas para proveedores.</p></form>}</article>;
}
